/*
 * Copies a NUL-terminated byte string to the destination while subtracting 0x20
 * from each unsigned source byte; writes 0xff as the destination terminator.
 * Neither input nor output bounds are checked.
 */
// FUNCTION: FF7 0x006cdc20
void __cdecl InputConfig_AsciiToFF7Text(char *dst, char *src)
{
    int val;

    val = 0;
    while (src[val]) {
        dst[val] = (unsigned char)src[val] - 0x20;
        val++;
    }
    dst[val] = -1;
}

/*
 * Copies the live input configuration (the 300 bytes of g_InputBindings) into the edit
 * buffer g_MenuKeyConfigEditBindingsRow0.
 */
// FUNCTION: FF7 0x006cdc65
void __cdecl InputConfig_BeginEdit(void)
{
    *(MenuInputBindingTable *)&g_MenuKeyConfigEditBindingsRow0 = *(MenuInputBindingTable *)g_InputBindings;
}

/*
 * Commits the edit buffer g_MenuKeyConfigEditBindingsRow0 to the live input configuration and to the
 * saved copy g_MenuKeyConfigSavedInputBuffer.
 */
// FUNCTION: FF7 0x006cdc7f
void __cdecl InputConfig_CommitEdit(void)
{
    *(MenuInputBindingTable *)g_InputBindings = *(MenuInputBindingTable *)&g_MenuKeyConfigEditBindingsRow0;
    g_MenuKeyConfigSavedInputBuffer = *(MenuInputBindingTable *)&g_MenuKeyConfigEditBindingsRow0;
}

/*
 * Capture one pending keyboard event or joystick binding code. Keep the pending-
 * count call in the for test: the original queries it each time.
 */
// FUNCTION: FF7 0x006cdcaa
int __cdecl InputConfig_CaptureSource(int source)
{
    int *eventPtr;
    int eventIndex;
    JoystickOutput *pJoyPoll;

    switch (source) {
    case MENU_KEY_CONFIG_CAPTURE_KEYBOARD:
        for (eventIndex = 0; eventIndex < DI_KeyboardGetPendingCount(); eventIndex++) {
            eventPtr = (int *)DI_KeyboardGetNextEvent();
            if (eventPtr && (eventPtr[1] & 0x80)) {
                return *eventPtr;
            }
        }
        break;
    case MENU_KEY_CONFIG_CAPTURE_JOYSTICK:
        pJoyPoll = Joystick_Poll();
        if (Input_GetPressed(INPUT_JOY_BUTTON_1)) {
            return INPUT_SOURCE_JOY_BUTTON_0;
        }
        if (Input_GetPressed(INPUT_JOY_BUTTON_3)) {
            return INPUT_SOURCE_JOY_BUTTON_2;
        }
        if (pJoyPoll) {
            if (pJoyPoll->up) {
                return INPUT_SOURCE_JOY_UP;
            }
            if (pJoyPoll->down) {
                return INPUT_SOURCE_JOY_DOWN;
            }
            if (pJoyPoll->left) {
                return INPUT_SOURCE_JOY_LEFT;
            }
            if (pJoyPoll->right) {
                return INPUT_SOURCE_JOY_RIGHT;
            }
            if (pJoyPoll->buttons[1]) {
                return INPUT_SOURCE_JOY_BUTTON_1;
            }
            if (pJoyPoll->buttons[3]) {
                return INPUT_SOURCE_JOY_BUTTON_3;
            }
            if (pJoyPoll->buttons[4]) {
                return INPUT_SOURCE_JOY_BUTTON_4;
            }
            if (pJoyPoll->buttons[5]) {
                return INPUT_SOURCE_JOY_BUTTON_5;
            }
            if (pJoyPoll->buttons[6]) {
                return INPUT_SOURCE_JOY_BUTTON_6;
            }
            if (pJoyPoll->buttons[7]) {
                return INPUT_SOURCE_JOY_BUTTON_7;
            }
            if (pJoyPoll->buttons[8]) {
                return INPUT_SOURCE_JOY_BUTTON_8;
            }
            if (pJoyPoll->buttons[9]) {
                return INPUT_SOURCE_JOY_BUTTON_9;
            }
        }
        break;
    }
    return 0;
}

/*
 * Enters the input configuration screen: a cursor over the 2 x 14 binding slots in
 * g_MenuKeyConfigCursor, the edit state and flash timer cleared, and the edit buffer
 * loaded.
 */
// FUNCTION: FF7 0x006cde2b
void __cdecl InputConfig_ScreenEnter(void)
{
    MenuCursor_Init(&g_MenuKeyConfigCursor, 0, 0, 2, 0xE, 0, 0, 2, 0xE, 0, 0, 0, 1, 0, 0);
    g_MenuKeyConfigEditState = MENU_KEY_CONFIG_BROWSE;
    g_MenuKeyConfigFlashTimer = 0;
    InputConfig_BeginEdit();
}

/*
 * Draws the input configuration screen in the selected scale, including two
 * binding columns, fourteen action rows, selected-binding highlight, cursor and
 * capture/help text. In browsing state updates the cursor, begins keyboard or
 * joystick capture on confirmation, or commits edits and sets the caller exit
 * flag on cancellation. In a capture state, a new binding replaces the slot's code
 * and swaps it with any other action that held the captured code.
 *
 * bindSlot counts the bits of the slot's action mask, one past the action's bit
 * index; the draw loops read the edit buffer from the word before it (g_MenuKeyConfigEditHeaderWord),
 * the capture code decrements bindSlot first and reads from g_MenuKeyConfigEditBindingsRow0.
 */
// FUNCTION: FF7 0x006cde72
void __cdecl InputConfig_ScreenFrame(int *exitFlag)
{
#pragma pack(push, 1)
    /* Locals by stack slot: see FRAME UNION in lib/codegen.h. */
    union {
        unsigned char storage[92];
        int actionRow;
        struct { unsigned char pad_to_4[0x4]; int bitIndex; };
        struct { unsigned char pad_to_8[0x8]; int row1x; };
        struct { unsigned char pad_to_C[0xC]; int labelRow1x; };
        struct { unsigned char pad_to_10[0x10]; int column1x; };
        struct { unsigned char pad_to_14[0x14]; int row2x; };
        struct { unsigned char pad_to_18[0x18]; int labelRow2x; };
        struct { unsigned char pad_to_1C[0x1C]; int column2x; };
        struct { unsigned char pad_to_20[0x20]; int captureSource; };
        struct { unsigned char pad_to_24[0x24]; int encodedText; };
        struct { unsigned char pad_to_40[0x40]; int labelX; };
        struct { unsigned char pad_to_44[0x44]; int bindSlot; };
        struct { unsigned char pad_to_48[0x48]; int labelStride; };
        struct { unsigned char pad_to_4C[0x4C]; int textWidth; };
        struct { unsigned char pad_to_50[0x50]; int windowIndex; };
        struct { unsigned char pad_to_54[0x54]; short boxX; };
        struct { unsigned char pad_to_56[0x56]; short boxY; };
        struct { unsigned char pad_to_58[0x58]; short boxWidth; };
        struct { unsigned char pad_to_5A[0x5A]; short boxHeight; };
    } frame;
#pragma pack(pop)

    frame.labelX = 0x32;
    frame.labelStride = 0x32;
    if (g_MenuIsSmallViewport320x240 != 1) {
        for (frame.windowIndex = 0; frame.windowIndex < 2; frame.windowIndex++) {
            Menu_DrawWindowFrame2x(&g_MenuKeyConfigWindowRects2x[frame.windowIndex], 0.2f);
        }
        Menu_DrawEncodedString2x(0xC8, 0x4B, g_MenuKeyConfigPromptLabels.rows[17], 4, 0.1f);
        Menu_DrawEncodedString2x(0x190, 0x4B, g_MenuKeyConfigPromptLabels.joystickTitle, 4, 0.1f);
        for (frame.labelRow2x = 0; frame.labelRow2x < 0xE; frame.labelRow2x++) {
            Menu_DrawEncodedString2x(frame.labelX, frame.labelRow2x * 0x18 + 0x7C, g_MenuKeyConfigPromptLabels.rows[frame.labelRow2x + 3], 3, 0.1f);
        }
        for (frame.column2x = 0; frame.column2x < 2; frame.column2x++) {
            for (frame.row2x = 0; frame.row2x < 0xE; frame.row2x++) {
                frame.bindSlot = 0;
                while (*(int *)((char *)g_MenuKeyConfigSlotMasks + (frame.column2x * 0xA8 + frame.row2x * 0xC)) >> frame.bindSlot != 0) {
                    frame.bindSlot++;
                }
                InputConfig_AsciiToFF7Text((char *)&frame.encodedText, g_MenuKeyNamePointers[*(int *)((char *)&g_MenuKeyConfigEditHeaderWord + (frame.column2x * 0x64 + frame.bindSlot * 4))]);
                if (frame.column2x == g_MenuKeyConfigCursor.col && frame.row2x == g_MenuKeyConfigCursor.row && g_MenuKeyConfigEditState != MENU_KEY_CONFIG_BROWSE) {
                    frame.textWidth = Menu_MeasureEncodedString2x((unsigned char *)&frame.encodedText);
                    frame.boxX = *(int *)((char *)g_MenuKeyConfigSlotPos + (frame.column2x * 0xA8 + frame.row2x * 0xC)) - 4;
                    frame.boxY = frame.row2x * 0x18 + 0x7A;
                    frame.boxWidth = frame.textWidth + 6;
                    frame.boxHeight = 0x1A;
                    Menu_DrawRaisedBox2x(&frame.boxX, 0.1f);
                }
                Menu_DrawEncodedString2x(*(int *)((char *)g_MenuKeyConfigSlotPos + (frame.column2x * 0xA8 + frame.row2x * 0xC)), frame.row2x * 0x18 + 0x7C, (unsigned char *)&frame.encodedText, 7, 0.1f);
            }
        }
        Menu_DrawMoreTextArrow2x(g_MenuKeyConfigCursor.col * 0xC8 + 0x9B, g_MenuKeyConfigCursor.row * 0x18 + 0x81, 0);
        switch (g_MenuKeyConfigEditState) {
        case MENU_KEY_CONFIG_BROWSE:
            if ((g_MenuKeyConfigFlashTimer & 0x80) != 0) {
                Menu_DrawEncodedString2x(0x1A, 0xD, g_MenuKeyConfigPromptLabels.rows[1], 7, 0.1f);
            } else {
                Menu_DrawEncodedString2x(0x1A, 0xD, g_MenuKeyConfigPromptLabels.rows[0], 7, 0.1f);
            }
            break;
        case MENU_KEY_CONFIG_CAPTURE_KEYBOARD:
        case MENU_KEY_CONFIG_CAPTURE_JOYSTICK:
            Menu_DrawEncodedString2x(0x1A, 0xD, g_MenuKeyConfigPromptLabels.rows[2], 7, 0.1f);
        }
    } else {
        for (frame.windowIndex = 0; frame.windowIndex < 2; frame.windowIndex++) {
            Menu_DrawWindowFrame1x(&g_MenuKeyConfigWindowRects1x[frame.windowIndex], 0.2f);
        }
        Menu_DrawEncodedString1x(0x64, 0x26, g_MenuKeyConfigPromptLabels.rows[17], 4, 0.1f);
        Menu_DrawEncodedString1x(0xC8, 0x26, g_MenuKeyConfigPromptLabels.joystickTitle, 4, 0.1f);
        for (frame.labelRow1x = 0; frame.labelRow1x < 0xE; frame.labelRow1x++) {
            Menu_DrawEncodedString1x(frame.labelX >> 1, frame.labelRow1x * 0xC + 0x3A, g_MenuKeyConfigPromptLabels.rows[frame.labelRow1x + 3], 3, 0.1f);
        }
        for (frame.column1x = 0; frame.column1x < 2; frame.column1x++) {
            for (frame.row1x = 0; frame.row1x < 0xE; frame.row1x++) {
                frame.bindSlot = 0;
                while (*(int *)((char *)g_MenuKeyConfigSlotMasks + (frame.column1x * 0xA8 + frame.row1x * 0xC)) >> frame.bindSlot != 0) {
                    frame.bindSlot++;
                }
                InputConfig_AsciiToFF7Text((char *)&frame.encodedText, g_MenuKeyNamePointers[*(int *)((char *)&g_MenuKeyConfigEditHeaderWord + (frame.column1x * 0x64 + frame.bindSlot * 4))]);
                if (frame.column1x == g_MenuKeyConfigCursor.col && frame.row1x == g_MenuKeyConfigCursor.row && g_MenuKeyConfigEditState != MENU_KEY_CONFIG_BROWSE) {
                    frame.textWidth = Menu_MeasureEncodedString1x((unsigned char *)&frame.encodedText);
                    frame.boxX = (*(int *)((char *)g_MenuKeyConfigSlotPos + (frame.column1x * 0xA8 + frame.row1x * 0xC)) >> 1) - 2;
                    frame.boxY = frame.row1x * 0xC + 0x39;
                    frame.boxWidth = frame.textWidth + 3;
                    frame.boxHeight = 0xD;
                    Menu_DrawRaisedBox1x(&frame.boxX, 0.1f);
                }
                Menu_DrawEncodedString1x(*(int *)((char *)g_MenuKeyConfigSlotPos + (frame.column1x * 0xA8 + frame.row1x * 0xC)) >> 1, frame.row1x * 0xC + 0x3A, (unsigned char *)&frame.encodedText, 7, 0.1f);
            }
        }
        Menu_DrawMoreTextArrow1x(g_MenuKeyConfigCursor.col * 0x64 + 0x4D, g_MenuKeyConfigCursor.row * 0xC + 0x3D, 0);
        switch (g_MenuKeyConfigEditState) {
        case MENU_KEY_CONFIG_BROWSE:
            if ((g_MenuKeyConfigFlashTimer & 0x80) != 0) {
                Menu_DrawEncodedString1x(0xD, 7, g_MenuKeyConfigPromptLabels.rows[1], 7, 0.1f);
            } else {
                Menu_DrawEncodedString1x(0xD, 7, g_MenuKeyConfigPromptLabels.rows[0], 7, 0.1f);
            }
            break;
        case MENU_KEY_CONFIG_CAPTURE_KEYBOARD:
        case MENU_KEY_CONFIG_CAPTURE_JOYSTICK:
            Menu_DrawEncodedString1x(0xD, 7, g_MenuKeyConfigPromptLabels.rows[2], 7, 0.1f);
        }
    }
    switch (g_MenuKeyConfigEditState) {
    case MENU_KEY_CONFIG_BROWSE:
        MenuCursor_Update(&g_MenuKeyConfigCursor);
        if (Input_GetPressed(INPUT_CIRCLE) != 0) {
            SfxPreloadAndPlayOnChannel5(SFX_MENU_CURSOR);
            g_MenuKeyConfigEditState = (g_MenuKeyConfigCursor.col != 0) ? MENU_KEY_CONFIG_CAPTURE_JOYSTICK : MENU_KEY_CONFIG_CAPTURE_KEYBOARD;
            DI_KeyboardFlushBuffer();
            Input_Update(0);
        } else if (Input_GetPressed(INPUT_CIRCLE) != 0) {
            SfxPreloadAndPlayOnChannel5(SFX_MENU_CURSOR);
            g_MenuKeyConfigEditState = (g_MenuKeyConfigCursor.col != 0) ? MENU_KEY_CONFIG_CAPTURE_JOYSTICK : MENU_KEY_CONFIG_CAPTURE_KEYBOARD;
            DI_KeyboardFlushBuffer();
            Input_Update(0);
        } else if (Input_GetPressed(INPUT_CROSS) != 0) {
            if (1 != 0) { /* Constant condition kept for /Od branch layout; see lib/codegen.h. */
                *exitFlag = 1;
                SfxPreloadAndPlayOnChannel5(SFX_MENU_CANCEL);
                InputConfig_CommitEdit();
                Input_Update(0);
            } else {
                SfxPreloadAndPlayOnChannel5(SFX_MENU_INVALID);
            }
        }
        break;
    case MENU_KEY_CONFIG_CAPTURE_KEYBOARD:
    case MENU_KEY_CONFIG_CAPTURE_JOYSTICK:
        frame.captureSource = InputConfig_CaptureSource(g_MenuKeyConfigEditState);
        if (frame.captureSource != 0) {
            frame.bindSlot = 0;
            while (*(int *)((char *)g_MenuKeyConfigSlotMasks + (g_MenuKeyConfigCursor.col * 0xA8 + g_MenuKeyConfigCursor.row * 0xC)) >> frame.bindSlot != 0) {
                frame.bindSlot++;
            }
            frame.bindSlot--;
            for (frame.actionRow = 0; frame.actionRow < 0xE; frame.actionRow++) {
                frame.bitIndex = 0;
                while (*(int *)((char *)g_MenuKeyConfigSlotMasks + frame.actionRow * 0xC) >> frame.bitIndex != 0) {
                    frame.bitIndex++;
                }
                frame.bitIndex--;
                if (g_MenuKeyConfigEditBindingsRow0[frame.bitIndex] == frame.captureSource) {
                    g_MenuKeyConfigEditBindingsRow0[frame.bitIndex] = *(int *)((char *)&g_MenuKeyConfigEditBindingsRow0 + (g_MenuKeyConfigCursor.col * 0x64 + frame.bindSlot * 4));
                }
                frame.bitIndex = 0;
                while (*(int *)((char *)g_MenuKeyConfigJoystickSlotMasks + frame.actionRow * 0xC) >> frame.bitIndex != 0) {
                    frame.bitIndex++;
                }
                frame.bitIndex--;
                if (g_MenuKeyConfigEditBindingsRow1Words[frame.bitIndex] == frame.captureSource) {
                    g_MenuKeyConfigEditBindingsRow1Words[frame.bitIndex] = *(int *)((char *)&g_MenuKeyConfigEditBindingsRow0 + (g_MenuKeyConfigCursor.col * 0x64 + frame.bindSlot * 4));
                }
            }
            *(int *)((char *)&g_MenuKeyConfigEditBindingsRow0 + (g_MenuKeyConfigCursor.col * 0x64 + frame.bindSlot * 4)) = frame.captureSource;
            DI_KeyboardFlushBuffer();
            Input_Update(0);
            g_MenuKeyConfigEditState = MENU_KEY_CONFIG_BROWSE;
            g_MenuKeyConfigWaitTimer = 1;
            SfxPreloadAndPlayOnChannel5(SFX_MENU_CONFIRM);
            g_MenuKeyConfigFlashTimer = 0;
        }
    }
    g_MenuKeyConfigFlashTimer++;
}

/*
 * Reverts the live input configuration to the saved copy
 * g_MenuKeyConfigSavedInputBuffer.
 */
// FUNCTION: FF7 0x006ce64b
void __cdecl InputConfig_RevertToSaved(void)
{
    *(MenuInputBindingTable *)g_InputBindings = g_MenuKeyConfigSavedInputBuffer;
}

/*
 * Writes ff7input.cfg into the save directory g_InitPath_AppPath: one byte with
 * the input mode (bits 2-3 of gSavemap.options) followed by the
 * 0x12C-byte input configuration.
 */
// FUNCTION: FF7 0x006ce665
void __cdecl InputConfig_SaveToFile(void)
{
    int fileHandle;
    unsigned char inputMode;

    fileHandle = 0;
    inputMode = gSavemap.options >> 2 & 3;
    // STRING: FF7 0x0091bd48
    sprintf((char *)g_LoadMenuSlotBuffer, "%sff7input.cfg", g_InitPath_AppPath);
    fileHandle = OpenFileSimple(FILE_OPEN_CREATE, g_LoadMenuSlotBuffer);
    if (fileHandle != 0) {
        WriteFileData(1, &inputMode, (FileHandle *)fileHandle);
        WriteFileData(0x12C, &g_InputBindings, (FileHandle *)fileHandle);
        CloseFileEx((FileHandle *)fileHandle);
    }
}

/*
 * Opens ff7input.cfg under g_InitPath_AppPath. If the first read byte is 1, reads
 * 0x12C configuration bytes and sets g_MenuKeyConfigAssignTarget to 1; other
 * header values or open failure load keyboard defaults.
 */
// FUNCTION: FF7 0x006ce6ec
void __cdecl InputConfig_LoadFromFile(void)
{
    int fileHandle;
    int headerByte;

    fileHandle = 0;
    // STRING: FF7 0x0091bd58
    sprintf((char *)g_LoadMenuSlotBuffer, "%sff7input.cfg", g_InitPath_AppPath);
    fileHandle = OpenFileSimple(FILE_OPEN_READ, g_LoadMenuSlotBuffer);
    if (fileHandle != 0) {
        ReadFileData(1, &headerByte, (FileHandle *)fileHandle);
        if ((headerByte & 0xFF) == 1) {
            ReadFileData(0x12C, &g_InputBindings, (FileHandle *)fileHandle);
            g_MenuKeyConfigAssignTarget = 1;
        } else {
            Input_LoadKeyboardDefaults();
        }
        CloseFileEx((FileHandle *)fileHandle);
    } else {
        Input_LoadKeyboardDefaults();
    }
    g_MenuKeyConfigSavedInputBuffer = *(MenuInputBindingTable *)g_InputBindings;
}

/*
 * Clears bits 2 and 3 of the input configuration word, then ORs in
 * g_MenuKeyConfigAssignTarget shifted left by two. The shifted value is not masked
 * to two bits, so other set bits can also affect the configuration word.
 */
// FUNCTION: FF7 0x006ce79b
void __cdecl InputConfig_SyncCustomFlag(void)
{
    gSavemap.options &= 0xFFF3;
    gSavemap.options |= g_MenuKeyConfigAssignTarget << 2;
}
